/**
 * Series landing page generation
 *
 * 系列落地页与总览页的生成
 */

import type { App, Page } from 'vuepress'
import type { ThemeOptions, ThemePageData } from '../../../shared/index.js'
import { createPage } from 'vuepress/core'
import { logger } from '../../utils/index.js'
import { collectSeries } from './collect.js'
import { resolveSeriesIndexPath, resolveSeriesOptions } from './options.js'

/**
 * Page types generated by this feature.
 *
 * 本功能生成的页面类型。
 */
const SERIES_PAGE_TYPES = new Set(['posts-series', 'posts-series-index'])

/**
 * Frontmatter shared by the generated pages: they are a table of contents, not a
 * document, so every page feature that needs a source file is switched off.
 *
 * 生成页面共用的 frontmatter：它们是目录页而不是文档页，
 * 所有依赖源文件的页面特性一律关闭。
 */
const SERIES_PAGE_FRONTMATTER = {
  sidebar: false,
  aside: false,
  prev: false,
  next: false,
  comments: false,
  editLink: false,
  contributors: false,
  changelog: false,
  lastUpdated: false,
} as const

/**
 * Collect the paths occupied by real pages.
 *
 * Landing pages generated by this feature are excluded, so that a series is never
 * considered to conflict with itself.
 *
 * 收集真实页面已占用的路径。本功能生成的页面会被排除，避免系列与自身冲突。
 *
 * @param pages - All pages / 全部页面
 */
export function collectOccupiedPaths(pages: Page<ThemePageData>[]): Set<string> {
  const paths = new Set<string>()

  for (const page of pages) {
    if (SERIES_PAGE_TYPES.has(page.data.type as string))
      continue
    paths.add(page.path)
  }

  return paths
}

/**
 * Resolve the page creation tasks of every series (landing pages + overview pages).
 *
 * The tasks are returned instead of being executed, so the caller can merge them into
 * its own `pMap` batch and avoid injecting routes twice.
 *
 * 解析所有系列的页面创建任务（落地页 + 总览页）。返回任务而不是立即创建，
 * 调用方可以合并进自己的 `pMap` 批次，避免二次注入路由。
 *
 * @param app - VuePress application instance / VuePress 应用实例
 * @param options - Theme options / 主题配置
 */
export async function resolveSeriesPageTasks(
  app: App,
  options: ThemeOptions,
): Promise<Array<() => Promise<Page>>> {
  const pages = app.pages as Page<ThemePageData>[]
  const occupiedPaths = collectOccupiedPaths(pages)
  const series = collectSeries(pages, options, {
    isBuild: app.env.isBuild,
    occupiedPaths,
    // 告警统一由 `prepareSeries` 输出一次，避免同一问题在构建日志中重复出现
    // Warnings are reported once by `prepareSeries` to avoid duplicated log lines
    quiet: true,
  })

  const tasks: Array<() => Promise<Page>> = []

  for (const item of series) {
    if (!item.pagePath)
      continue

    const path = item.pagePath

    tasks.push(() => createPage(app, {
      path,
      frontmatter: {
        ...SERIES_PAGE_FRONTMATTER,
        lang: item.lang,
        _pageLayout: 'posts-series',
        title: item.title,
        description: item.description,
        seriesId: item.id,
      },
    }))
  }

  // 系列总览页：每个语言一个，路径为 `linkPrefix` 的根路径
  // Series overview page: one per locale, at the root of `linkPrefix`
  const locales = new Set(series.map(item => item.locale))

  for (const locale of locales) {
    const resolved = resolveSeriesOptions(options, locale)

    if (!resolved?.index)
      continue

    const path = resolveSeriesIndexPath(resolved, locale)

    if (occupiedPaths.has(path)) {
      logger.warn(`[series] series overview page path ${path} is already used, it has been skipped.`)
      continue
    }

    occupiedPaths.add(path)

    const lang = series.find(item => item.locale === locale)?.lang ?? ''
    const title = options.locales?.[locale]?.seriesIndexText || 'Series'

    tasks.push(() => createPage(app, {
      path,
      frontmatter: {
        ...SERIES_PAGE_FRONTMATTER,
        lang,
        _pageLayout: 'posts-series-index',
        title,
      },
    }))
  }

  return tasks
}
